"use strict";(self.webpackChunksite=self.webpackChunksite||[]).push([["7069"],{53e3(e,n,a){a.r(n),a.d(n,{metadata:()=>t,default:()=>c,frontMatter:()=>s,contentTitle:()=>r,toc:()=>d,assets:()=>l});var t=JSON.parse('{"id":"radiopi","title":"RadioPi","description":"RadioPi is the web radio of the ECP (Ecole Centrale de Paris). RadioPi runs many channels. There are topical channels (Reggae, Hip-Hop, Jazz, ...). On\u2026","source":"@site/versioned_docs/version-2.2.5/radiopi.md","sourceDirName":".","slug":"/radiopi","permalink":"/doc-2.2.5/radiopi","draft":false,"unlisted":false,"tags":[],"version":"2.2.5","frontMatter":{"title":"RadioPi","description":"RadioPi is the web radio of the ECP (Ecole Centrale de Paris). RadioPi runs many channels. There are topical channels (Reggae, Hip-Hop, Jazz, ...). On\u2026"},"sidebar":"docs","previous":{"title":"Geekradio","permalink":"/doc-2.2.5/geekradio"},"next":{"title":"Frequence3","permalink":"/doc-2.2.5/frequence3"}}'),i=a(74848),o=a(28453);let s={title:"RadioPi",description:"RadioPi is the web radio of the ECP (Ecole Centrale de Paris). RadioPi runs many channels. There are topical channels (Reggae, Hip-Hop, Jazz, ...). On\u2026"},r,l={},d=[{value:"The migration process",id:"the-migration-process",level:3}];function u(e){let n={a:"a",code:"code",h3:"h3",p:"p",pre:"pre",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.a,{href:"http://www.radiopi.org",children:"RadioPi"})," is the web radio of the ECP (Ecole Centrale de Paris). RadioPi runs many channels.\nThere are topical channels (Reggae, Hip-Hop, Jazz, ...). On top of that, they periodically broadcast live shows,\nwhich are relayed on all channels."]}),"\n",(0,i.jsx)(n.p,{children:"We met a RadioPi manager right after having released Liquidsoap 0.2.0, and he was seduced by the system. They needed\nquite complex features, which they were at that time fulfilling using dirty tricks, loads of obfuscated scripts.\nUsing Liquidsoap now allow them to do all they want in an integrated way, but also provided new features."}),"\n",(0,i.jsx)(n.h3,{id:"the-migration-process",children:"The migration process"}),"\n",(0,i.jsx)(n.p,{children:"Quite easy actually. They used to have many instances Ices2, each of these calling a Perl script to get the next song.\nOther scripts were used for switching channels to live shows."}),"\n",(0,i.jsx)(n.p,{children:"Now they have this single Liquidsoap script, no more. It calls external scripts to interact with their web-based song\nscheduling system. And they won new features: blank detection and distributed encoding."}),"\n",(0,i.jsx)(n.p,{children:"The first machine gets its files from a ftp server opened on the second machine.\nLiquidsoap handles download automatically."}),"\n",(0,i.jsxs)(n.p,{children:["Each file is given by an external script, ",(0,i.jsx)(n.code,{children:"radiopilote-getnext"}),",\nwhose answer looks as follows (except that it's on a single line):"]}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:'annotate:file_id="3541",length="400.613877551",\\\n type="chansons",title="John Holt - Holigan",\\\n artist="RadioPi - Canal reggae",\\\n album="Studio One SeleKta! - Album Studio 1 12",\\\n canal="reggae":ftp://***:***@host/files/3541.mp3\n'})}),"\n",(0,i.jsx)(n.p,{children:"Note that we use annotate to pass some variables to liquidsoap..."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-liquidsoap",children:'#!/usr/bin/liquidsoap\n\n# Standard settings\nlog.file.set(true)\nlog.file.path.set("/var/log/liquidsoap/pi.log")\nlog.stdout.set(false)\ninit.daemon.set(true)\ninit.daemon.pidfile.path.set("/var/run/liquidsoap/pi.pid")\n\n#\xa0Enable telnet server\nsettings.server.telnet.set(true)\n\n# Enable harbor for any external\n# connection\nsettings.harbor.bind_addrs.set(["0.0.0.0"])\n\n#\xa0Verbose logs\nlog.level.set(4)\n\n# We use the scheduler intensively,\n# therefore we create many queues.\nsettings.scheduler.generic_queues.set(5)\nsettings.scheduler.fast_queues.set(3)\nsettings.scheduler.non_blocking_queues.set(3)\n\n# === Settings ===\n\n# The host to request files\nstream = "XXXxXXXx"\n# The command to request files\nscripts = "ssh XXxxxXXX@#{stream} \'/path/to/scripts/"\n#\xa0A substitution on the returned path\nsed = " | sed -e s#/path/to/files/#ftp://user:password@#{stream}/#\'"\n\n# Enable replay gain\nenable_replaygain_metadata ()\n\npass = "XXxXXXXx"\nice_host = "localhost"\n\ndescr = "RadioPi"\nurl = "http://radiopi.org"\n\n# === Live ===\n\n# A live source, on which we strip blank (make the source\n#\xa0unavailable when streaming blank)\nlive =\n blank.strip(\n input.harbor(id="live", port=8000, password=pass,\n buffer=8.,max=20.,"live.ogg"),\n length=10., threshold=-50.)\n\n#\xa0This source relays the live data, when available,\n# to the other streamer, in uncompressed format (WAV)\noutput.icecast(%wav, host=stream,\n port=8005, password=pass,\n mount="live.ogg", fallible=true,\n live)\n\n#\xa0This source relays the live source to "live.ogg". This\n# is used for debugging purposes, to see what is sent\n#\xa0to the harbor source.\noutput.icecast(%vorbis, host="127.0.0.1",\n port=8080, password=pass,\n mount="live.ogg", fallible=true,\n live)\n\n#\xa0This source starts an archive of the live stream\n# when available\ntitle = \'$(if $(title),"$(title)",\\\n "Emission inconnue")$(if $(artist), \\\n " par $(artist)") - %m-%d-%Y, %H:%M:%S\'\noutput.file(%vorbis, reopen_on_metadata=true,\n fallible=true,\n "/data/archives/brutes/" ^ title ^ ".ogg",\n live)\n\n# === Channels ===\n\n# Specialize the output functions by partial application\noutput.icecast = output.icecast(description=descr, url=url)\nout = output.icecast(host=ice_host,port=8080,password=pass,fallible=true)\nout_aac32 = out(%fdkaac(bitrate=32))\nout_aac = out(%fdkaac(bitrate=64))\nout = out(%mp3)\n\n# A file for playing during failures\ninterlude =\n single("/home/radiopi/fallback.mp3")\n\n# Lastfm submission\ndef lastfm (m) =\n if (m["type"] == "chansons") then\n if (m["canal"] == "reggae" or m["canal"] == "Jazz" or m["canal"] == "That70Sound") then\n canal =\n if (m["canal"] == "That70Sound") then\n "70sound"\n else\n m["canal"]\n end\n user = "radiopi-" ^ canal\n lastfm.submit(user=user,password="xXXxx",m)\n end\n end\nend\n\n# === Basic sources ===\n\n# Custom crossfade to deal with jingles..\ndef crossfade (~start_next=5.,~fade_in=3.,~fade_out=3.,\n ~default=(fun (a,b) -> sequence([a, b])),\n ~high=-15., ~medium=-32., ~margin=4.,\n ~width=2.,~conservative=false,s)\n fade.out = fade.out(type="sin",duration=fade_out)\n fade.in = fade.in(type="sin",duration=fade_in)\n add = fun (a,b) -> add(normalize=false,[b, a])\n log = log(label="crossfade")\n\n def transition(a,b,ma,mb,sa,sb)\n\n list.iter(fun(x)-> log(level=4,"Before: #{x}"),ma)\n list.iter(fun(x)-> log(level=4,"After : #{x}"),mb)\n\n if ma["type"] == "jingles" or mb["type"] == "jingles" then\n log("Old or new file is a jingle: sequenced transition.")\n sequence([sa, sb])\n elsif\n # If A and B are not too loud and close, fully cross-fade them.\n a <= medium and b <= medium and abs(a - b) <= margin\n then\n log("Old <= medium, new <= medium and |old-new| <= margin.")\n log("Old and new source are not too loud and close.")\n log("Transition: crossed, fade-in, fade-out.")\n add(fade.out(sa),fade.in(sb))\n\n elsif\n # If B is significantly louder than A, only fade-out A.\n # We don\'t want to fade almost silent things, ask for >medium.\n b >= a + margin and a >= medium and b <= high\n then\n log("new >= old + margin, old >= medium and new <= high.")\n log("New source is significantly louder than old one.")\n log("Transition: crossed, fade-out.")\n add(fade.out(sa),sb)\n\n elsif\n # Opposite as the previous one.\n a >= b + margin and b >= medium and a <= high\n then\n log("old >= new + margin, new >= medium and old <= high")\n log("Old source is significantly louder than new one.")\n log("Transition: crossed, fade-in.")\n add(sa,fade.in(sb))\n\n elsif\n # Do not fade if it\'s already very low.\n b >= a + margin and a <= medium and b <= high\n then\n log("new >= old + margin, old <= medium and new <= high.")\n log("Do not fade if it\'s already very low.")\n log("Transition: crossed, no fade.")\n add(sa,sb)\n\n # What to do with a loud end and a quiet beginning ?\n # A good idea is to use a jingle to separate the two tracks,\n # but that\'s another story.\n\n else\n # Otherwise, A and B are just too loud to overlap nicely,\n # or the difference between them is too large and overlapping would\n # completely mask one of them.\n log("No transition: using default.")\n default(sa, sb)\n end\n end\n\n cross(width=width, duration=start_next, conservative=conservative,\n transition,s)\nend\n\n# Create a radiopilote-driven source\ndef channel_radiopilote(~skip=true,name)\n log("Creating canal #{name}")\n\n #\xa0Request function\n def request () =\n log("Request for #{name}")\n ret = list.hd(process.read.lines(scripts^"radiopilote-getnext "^quote(name)^sed))\n log("Got answer: #{ret} for #{name}")\n [request.create(ret)]\n end\n\n #\xa0Create the request.dynamic.list source\n #\xa0Set conservative to true to queue\n #\xa0several songs in advance\n source =\n request.dynamic.list(conservative=true, length=400.,\n id="dyn_"^name,request,\n timeout=60.)\n\n # Apply normalization using replaygain\n #\xa0information\n source = amplify(1.,override="replay_gain", source)\n\n # Skip blank when asked to\n source =\n if skip then\n blank.skip(source, length=10., threshold=-40.)\n else\n source\n end\n\n #\xa0Submit new tracks on lastfm\n source = on_metadata(lastfm,source)\n\n #\xa0Tell the system when a new track\n # is played\n source = on_metadata(fun (meta) ->\n system(scripts ^ "radiopilote-feedback "\n ^quote(meta["canal"])^" "\n ^quote(meta["file_id"]) ^ "\'"), source)\n\n # Finally apply a smart crossfading\n crossfade(source)\nend\n\n# Basic source\njazz = channel_radiopilote("jazz")\ndiscoqueen = channel_radiopilote("discoqueen")\n# Avoid skipping blank with classic music !!\nclassique = channel_radiopilote(skip=false,"classique")\nThat70Sound = channel_radiopilote("That70Sound")\nmetal = channel_radiopilote("metal")\nreggae = channel_radiopilote("reggae")\nRock = channel_radiopilote("Rock")\n\n#\xa0Group those sources in a separate\n# clock (good for multithreading/multicore)\nclock.assign_new([jazz,That70Sound,metal,reggae])\n\n# === Mixing live ===\n\n# To create a channel from a basic source, add:\n# - a new-track notification for radiopilote\n# - metadata rewriting\n# - the live shows\n# - the failsafe \'interlude\' source to channels\n# - blank detection\ndef mklive(source) =\n # Transition function: if transitioning\n #\xa0to the live, fade out the old source\n # if transitioning from live, fade.in\n #\xa0the new source. NOTE: We cannot\n #\xa0skip the current song because\n #\xa0reloading new songs for all the\n #\xa0sources when live starts costs too much\n #\xa0CPU.\n def trans(old,new) =\n if source.id(new) == source.id(live) then\n log("Transition to live!")\n add([new,fade.out(old)])\n elsif source.id(old) == source.id(live) then\n log("Transitioning from live!")\n add([fade.in(new),old])\n else\n log("Dummy transition")\n new\n end\n end\n fallback(track_sensitive=false,\n transitions=[trans,trans,trans],\n [live,source,interlude])\nend\n\n# Create a channel using mklive(), encode and output it to icecast.\ndef mkoutput(~out=out,mount,source,name,genre)\n out(id=mount,mount=mount,name=name,genre=genre,\n mklive(source)\n )\nend\n\n# === Outputs ===\n\nmkoutput("jazz", jazz, "RadioPi - Canal Jazz","jazz")\nmkoutput("discoqueen", discoqueen, "RadioPi - Canal DiscoQueen","discoqueen")\nmkoutput("classique", classique, "RadioPi - Canal Classique","classique")\nmkoutput("That70Sound", That70Sound,\n "RadioPi - Canal That70Sound","That70Sound")\nmkoutput("metal", metal, "RadioPi - Canal Metal","metal")\nmkoutput("reggae", reggae, "RadioPi - Canal Reggae","reggae")\nmkoutput("Rock", Rock, "RadioPi - Canal Rock","Rock")\n\n# Test outouts\nmkoutput(out=out_aac,"reggae.aacp", reggae, "RadioPi - Canal Reggae \\\n (64 kbits AAC+ test stream)","reggae")\nmkoutput(out=out_aac32,"reggae.aacp32", reggae, "RadioPi - Canal Reggae \\\n (32 kbits AAC+ test stream)","reggae")\n'})}),"\n",(0,i.jsx)(n.p,{children:"The other machine has a similar configuration except that files are local, but this is exactly the same for liquidsoap !"}),"\n",(0,i.jsxs)(n.p,{children:["Using harbor, the live connects directly to liquidsoap, using port ",(0,i.jsx)(n.code,{children:"8000"})," (icecast runs on port ",(0,i.jsx)(n.code,{children:"8080"}),").\nThen, liquidsoap starts a relay to the other encoder, and both switch their channels to the new live."]}),"\n",(0,i.jsx)(n.p,{children:"Additionally, a file output is started upon live connection, in order to backup the stream. You could also add a relay to\nicecast in order to manually check what's received by the harbor."})]})}function c(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(u,{...e})}):u(e)}},28453(e,n,a){a.d(n,{R:()=>s,x:()=>r});var t=a(96540);let i={},o=t.createContext(i);function s(e){let n=t.useContext(o);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),t.createElement(o.Provider,{value:n},e.children)}}}]);